    public class SetEditionAndProductKeyTest : DismTestBase
    {
        private readonly string imageFilePath = "<path to image file>";
        private readonly string mountPath = "<path to folder>";
        private readonly string imageName = "Windows 11 Home";

        private readonly string targetEditionId = "Professional";
        private readonly string professionalGenericKey = "VK7JG-NPHTM-C97JM-9MPGT-3V66T";

        public SetEditionAndProductKeyTest(TestWimTemplate template, ITestOutputHelper testOutput)
            : base(template, testOutput)
        {
        }

        [Fact(Skip = "Execute manually after configuring the test variables above.")]
        public void SetEditionThenProductKey()
        {
            DismApi.MountImage(imageFilePath, mountPath, imageName);

            using (DismSession session = DismApi.OpenOfflineSession(mountPath))
            {
                DismApi.SetEdition(session, targetEditionId);
                DismApi.SetProductKey(session, professionalGenericKey);

                DismApi.GetCurrentEdition(session).ShouldBe(targetEditionId);
            }

            DismApi.UnmountImage(mountPath, false);
        }

        [Fact(Skip = "Execute manually after configuring the test variables above.")]
        public void SetEditionAndProductKey()
        {
            DismApi.MountImage(imageFilePath, mountPath, imageName);

            using (DismSession session = DismApi.OpenOfflineSession(mountPath))
            {
                DismApi.SetEditionAndProductKey(session, targetEditionId, professionalGenericKey);

                DismApi.GetCurrentEdition(session).ShouldBe(targetEditionId);
            }

            DismApi.UnmountImage(mountPath, false);
        }
    }
}
